-- Name: filter_data_tes(character varying, character varying, character varying, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.filter_data_tes(p_nama_tes character varying DEFAULT NULL::character varying, p_jenis_tes character varying DEFAULT NULL::character varying, p_penyelenggara character varying DEFAULT NULL::character varying, p_tgl_tes date DEFAULT NULL::date, p_user_id uuid DEFAULT NULL::uuid, p_status integer DEFAULT NULL::integer) RETURNS SETOF public.tb_tes
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT *
  FROM tb_tes
  WHERE (p_nama_tes IS NULL OR LOWER(nama_tes) LIKE LOWER('%' || p_nama_tes || '%'))
    AND (p_jenis_tes IS NULL OR LOWER(jenis_tes) LIKE LOWER('%' || p_jenis_tes || '%'))
    AND (p_penyelenggara IS NULL OR LOWER(penyelenggara) LIKE LOWER('%' || p_penyelenggara || '%'))
		AND (p_tgl_tes IS NULL OR tgl_tes = p_tgl_tes)
    AND is_deleted = false
		AND (p_user_id IS NULL OR user_id = p_user_id)
		AND (p_status IS NULL OR status = p_status);
END;
$$;


