--
-- TOC entry 357 (class 1255 OID 117199)
-- Name: filter_users(character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.filter_users(p_nama_lengkap character varying DEFAULT NULL::character varying, p_npm character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_kode_mhs character varying DEFAULT NULL::character varying, p_nidn character varying DEFAULT NULL::character varying, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT NULL::integer) RETURNS TABLE(user_id uuid, npm character, nidn character, email character varying, nama_lengkap character varying, kode_mhs character varying, image character varying, rank character varying, total_point integer, nip character)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE NOTICE 'Start of function filter_users';

  IF (
    p_nama_lengkap IS NULL AND
    p_npm IS NULL AND
    p_email IS NULL AND
    p_kode_mhs IS NULL AND
    p_nidn IS NULL AND
		p_limit IS NULL AND
		p_offset IS NULL
  ) THEN
    RAISE EXCEPTION 'At least one search parameter must be provided.';
  END IF;

  RETURN QUERY
  SELECT
    tb_users.user_id,
    tb_users.npm,
    tb_users.nidn,
    tb_users.email,
    tb_data_pribadi.nama_lengkap,
    tb_data_pribadi.kode_mhs,
    tb_data_pribadi.image,
    tb_data_pribadi.rank,
    tb_data_pribadi.total_point::integer,
		tb_data_pribadi.nip
  FROM
    tb_users
    JOIN tb_data_pribadi ON tb_data_pribadi.user_id = tb_users.user_id
  WHERE
    (p_nama_lengkap IS NULL OR LOWER(tb_data_pribadi.nama_lengkap) LIKE LOWER('%' || p_nama_lengkap || '%'))
    AND (p_npm IS NULL OR LOWER(tb_users.npm) LIKE LOWER('%' || p_npm || '%'))
    AND (p_nidn IS NULL OR LOWER(tb_users.nidn) LIKE LOWER('%' || p_nidn || '%'))
    AND (p_email IS NULL OR LOWER(tb_users.email) LIKE LOWER('%' || p_email || '%'))
    AND (p_kode_mhs IS NULL OR LOWER(tb_data_pribadi.kode_mhs) LIKE LOWER('%' || p_kode_mhs || '%'))
  ORDER BY tb_users.user_id
  LIMIT p_limit
  OFFSET p_offset;

  RAISE NOTICE 'End of function filter_users';
END;
$$;


ALTER FUNCTION public.filter_users(p_nama_lengkap character varying, p_npm character varying, p_email character varying, p_kode_mhs character varying, p_nidn character varying, p_limit integer, p_offset integer) OWNER TO postgres;

