INSERT INTO public.achievements VALUES ('c681b9af-9e9e-4818-bc90-80cafe506c17', 'TIAS Challenge/Tantangan ', 'Qualified', '1100-2300', 1100, 'image-1708815468273.jpg', 'GM1', 'Upgrade nilai TIAS Anda', 'Unlock fitur TIAS challange... Anda bisa mendapatkan informasi dari TIAS mobile app untuk kegiatan perlombaan yang dapat meningkatkan point TIAS Anda... Selamat berkompetisi.', 'lencana-1707289654481.png');
INSERT INTO public.achievements VALUES ('929cd7ae-3491-4d1c-9407-b987058e35b7', 'Sepeda Olahraga', 'Superior', '7500-9000', 7500, '1705904378132-image 63.png', 'GM5', 'Hadiah Superior', 'Jangan cuman otak tapi kesehatan juga harus dilatih... Yuk makin semangat dengan hadiah ini.. sepeda olahraga yang bisa bikin kamu makin sehat.', 'lencana-1707289589735.png');
INSERT INTO public.achievements VALUES ('73ed4488-34d1-4074-8981-98f5aa6f5735', 'Laptop MacBook', 'Legend', '10000-20000', 10000, '1705904422659-image 57.png', 'GM6', 'For the Legends', 'Alhamdulillah... sampai nih di level LEGEND... jarang-jarang loh ada yang bisa sampai sini... selamat ya', 'lencana-1707289573465.png');
INSERT INTO public.achievements VALUES ('38e7ae54-6766-4015-9a7c-62d3ca37b19a', 'Akses untuk akun udemy', 'Specialist', '5400-7400', 5400, '1705904335480-image 61.png', 'GM4', 'Hadiah Specialist', 'Tingkatkan semangat belajar kamu dengan adanya Akses ke situs Udemy. Anda dapat memanfaatkan berbagai fasilitas yang ada disana tanpa batas dan dengan akun premium... Asikkan...', 'lencana-1707289607714.png');
INSERT INTO public.achievements VALUES ('24753dd3-3fc4-4d4f-a994-066631db073b', 'Cetak Dokumen CV', 'Professional', '3900-5300', 3900, 'image-1708815955281.jpg', 'GM3', 'Buat yang udah masuk profesional', 'Wahh, sekarang Anda dapat mencetak curriculum vitae (CV)/data riwayat Anda dalam 1 kali klik, gak usah ribet-ribet untuk nulis daftar CV lagi, seluruh data yang telah Anda isikan akan tertarik, file akan ter-generate dalam bentuk PDF.', 'lencana-1708414941713.png');
INSERT INTO public.achievements VALUES ('f4fd404b-b251-4b2d-937e-e2afc845d83a', 'Rekomendasi Mahasiswa', 'Proficient', '2400-3800', 2400, 'image-1708815929603.png', 'GM2', 'Fitur penambah point', 'Selamat... Fitur rekomendasi dosen unlocked, Anda berhak mendapatkan rekomendasi dosen untuk meningkatkan point TIAS Anda... satu rekomendasi dari satu dosen bernilai 100 point lohhh....', 'lencana-1707289640344.png');
