INSERT INTO public.tb_berita VALUES ('eda766ad-af9e-4b9b-bc50-781f6d5d63a5', 'GEBYAR IT HIMATEKINFO', 'GEBYAR IT HIMATEKINFO adalah sebuah acara yang diselenggarakan oleh Himpunan Mahasiswa Teknik Informatika (HIMATEKINFO).', 'pamflet-1706092822728.jpeg', 'dokumen-1706092822744.pdf', 0, '2024-01-23 19:03:40', NULL, NULL, 'event');
