INSERT INTO public.tb_berita VALUES ('63c18668-396c-4ab8-8e92-418a288c6ae9', 'INFO PENTING‼️  Hai Sobat Ibn Khaldun Muda Ayo ikuti Program Kreatifitas Mahasiswa (PKM) 2024', '"🌟 Info Penting! 🌟 Sobat Ibn Khaldun Muda, siapkan dirimu untuk meraih prestasi dengan Program Kreativitas Mahasiswa (PKM) 2024! 🎓✨ Jadikan ide-ide brilianmu menjadi kenyataan dan gapai sukses bersama kami! 💡🚀 #PKM2024 #IbnKhaldunMuda #InovasiMahasiswa"', 'pamflet-1707447702789.jpeg', 'dokumen-1707449592791.pdf', 0, '2024-02-08 15:20:11', '2024-02-08 15:20:11', NULL, 'tantangan');
INSERT INTO public.tb_berita VALUES ('c4d022b3-4b86-44f1-a4c4-341155c83789', 'Terpilih Ber-KKN Di Madinah, 2 Mahasiswa FAI Langsung Diajak Umroh Gratis Oleh Pihak Pesantren', 'Dua Mahasiswa Fakultas Agama Islam (FAI) Universitas Ibn Khaldun (UIKA) Bogor, Muhammad HajanMakbula dan Muhammad Syahrul Ramadhan, membagikan pengalamannya selama menjalani KKN di Maahad Darul Azhar awal Hikmah, Madinah.
INSERT INTO public.tb_berita VALUES ('f4363973-f9f2-451f-96b1-f9f2b162ee62', 'Ragam Tarian Dan Adat Nusantara Warnai Penutupan PMM Batch 3 UIKA Bogor', 'Universitas Ibn Khaldun (UIKA) Bogor menggelar penutupan program Pertukaran Mahasiswa Merdeka (PMM) Batch 3, di Auditorium Prof. Abdullah Sidiq, Rabu (23/1/2024).
INSERT INTO public.tb_berita VALUES ('72ae2b9a-9c48-497d-ad97-6059e53d3034', 'KSR PMI Unit UIKA Menggelar Donor Darah Untuk Masyarakat Umum Dan Mahasiswa', 'KSR PMI Unit UIKA dan Fakultas Teknik dan sains menggelar kegiatan donor darah bagi mahasiswa dan masyarakat umum.
